class a{static async fetchAddress(t){const e=t.replace(/\D/g,"");if(e.length!==8)return null;try{const r=await(await fetch(`https://viacep.com.br/ws/${e}/json/`)).json();return r.erro?null:{street:r.logradouro,district:r.bairro,city:r.localidade,state:r.uf,zipCode:e}}catch(o){throw console.error("Erro ao buscar CEP:",o),new Error("Não foi possível buscar o CEP")}}}export{a as CEPService};
